FUNCTION_BLOCK FB_CNC_HydrostaticThermalComp
(* =========================================================================================
   LUMINA CYBER-PHYSICAL SYSTEMS ARCHITECTURE - IEC 61131-3 HIGH-INTEGRITY CONTROL
   DOMAIN: High-Precision Multi-Axis CNC Machine Tool
   SUBSYSTEM: Hydrostatic Spindle Bearing Gap Regulation & Volumetric Real-Time Thermal Comp
   SAFETY INTEGRITY LEVEL: SIL-3 / IEC 61508 / ISO 13849-1 Cat 4 PLe
   MATHEMATICAL MODEL:
     - 4x4 Discrete-Time Hydrodynamic-Hydrostatic Coupled State-Space Model
     - Receding-Horizon Model Predictive Gap Controller (MPC) with Cross-Coupling Decoupling
     - 2oo3 Triple Modular Redundancy (TMR) Pressure Voting & Sensor Health Analytics
     - ASTM D341 Dynamic Temperature-Viscosity Correction
     - 4-Node Finite Element Thermal Network for Spindle & Column Volumetric Expansion
     - Abbe Error Vector Correction at Tool Center Point (TCP)
   ========================================================================================= *)
VAR_INPUT
    bEnable                 : BOOL;     (* Master functional unit enable command *)
    bEStop                  : BOOL;     (* Hardware safety circuit ok (Active-High NC) *)
    bResetAlarms            : BOOL;     (* Asynchronous fault reset & diagnostic acknowledge strobe *)
    bSpindleRunning         : BOOL;     (* Machine tool spindle drive rotation active feedback *)
    rSpindleSpeed_Act       : REAL;     (* Actual spindle angular velocity [rpm] *)
    rSpindleLoadTorque      : REAL;     (* Spindle drive electromagnetic torque feedback [Nm] *)
    rSupplyPressure_Ch1     : REAL;     (* Hydraulic rail supply pressure transducer 1 [bar] *)
    rSupplyPressure_Ch2     : REAL;     (* Hydraulic rail supply pressure transducer 2 [bar] *)
    rSupplyPressure_Ch3     : REAL;     (* Hydraulic rail supply pressure transducer 3 [bar] *)
    rGapRadial_X1           : REAL;     (* Pocket X1 film clearance eddy-current sensor [um] *)
    rGapRadial_X2           : REAL;     (* Pocket X2 film clearance eddy-current sensor [um] *)
    rGapRadial_Y1           : REAL;     (* Pocket Y1 film clearance eddy-current sensor [um] *)
    rGapRadial_Y2           : REAL;     (* Pocket Y2 film clearance eddy-current sensor [um] *)
    rGapAxial_Z1            : REAL;     (* Thrust bearing front gap capacitive probe [um] *)
    rGapAxial_Z2            : REAL;     (* Thrust bearing rear gap capacitive probe [um] *)
    rTemp_SpindleNose       : REAL;     (* Front bearing sleeve RTD PT100 temperature [deg C] *)
    rTemp_RearBearing       : REAL;     (* Rear bearing sleeve RTD PT100 temperature [deg C] *)
    rTemp_MachineColumn     : REAL;     (* Machine tool structural column casting temp [deg C] *)
    rTemp_AmbientAir        : REAL;     (* Enclosure ambient environmental air temperature [deg C] *)
    rTemp_OilSump           : REAL;     (* Hydrostatic hydraulic reservoir fluid temp [deg C] *)
    rCycleTime_Sec          : REAL;     (* Deterministic PLC real-time task scan interval [s] *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* Hydrostatic bearing gap & thermal compensation operational *)
    bSpindleInhibit         : BOOL;     (* Spindle safety interlock (TRUE = spindle rotation prohibited) *)
    wStatusWord             : WORD;     (* System operational and health status word [16-bit bitfield] *)
    dwDiagnosticAlarms      : DWORD;    (* Comprehensive diagnostic alarms and trip word [32-bit bitfield] *)
    rServoValvePressureCmd_X: REAL;     (* Differential pocket pressure command for X-axis spool valve [bar] *)
    rServoValvePressureCmd_Y: REAL;     (* Differential pocket pressure command for Y-axis spool valve [bar] *)
    rServoValvePressureCmd_Z: REAL;     (* Axial pocket counter-thrust pressure command Z-axis [bar] *)
    rThermalCompOffset_X    : REAL;     (* Real-time volumetric TCP thermal compensation shift X [um] *)
    rThermalCompOffset_Y    : REAL;     (* Real-time volumetric TCP thermal compensation shift Y [um] *)
    rThermalCompOffset_Z    : REAL;     (* Real-time volumetric TCP thermal compensation shift Z [um] *)
    rBearingFilmThickness_Est:REAL;     (* Reconstructed minimum radial lubricating film thickness [um] *)
    rChillerSetpoint_DegC   : REAL;     (* Active closed-loop temperature setpoint for oil chiller [deg C] *)
    rEffectiveViscosity_cSt : REAL;     (* Calculated dynamic kinematic oil viscosity [mm2/s] *)
END_VAR

VAR
    (* --- 2oo3 Triple Modular Redundancy (TMR) Pressure Voting --- *)
    rPressVoted             : REAL;     (* Voted supply rail pressure from 2oo3 median [bar] *)
    bCh1_Healthy            : BOOL;     (* Channel 1 health flag *)
    bCh2_Healthy            : BOOL;     (* Channel 2 health flag *)
    bCh3_Healthy            : BOOL;     (* Channel 3 health flag *)
    rDiff_12                : REAL;     (* Inter-channel pressure differential Ch1-Ch2 [bar] *)
    rDiff_23                : REAL;     (* Inter-channel pressure differential Ch2-Ch3 [bar] *)
    rDiff_31                : REAL;     (* Inter-channel pressure differential Ch3-Ch1 [bar] *)
    iValidChannelCount      : INT;      (* Count of non-faulted pressure transmitters *)
    bTMR_Degraded           : BOOL;     (* Single sensor faulted, operating in 1oo2 fallback *)

    (* --- Fluid Dynamics & Viscosity Compensation (ASTM D341 Empirical Model) --- *)
    rT_Ref_DegC             : REAL := 40.0;     (* ISO standard reference temperature [deg C] *)
    rVisc_Nominal_cSt       : REAL := 46.0;     (* ISO VG 46 nominal viscosity at 40 C [mm2/s] *)
    rVisc_Slope_Beta        : REAL := 0.0295;   (* Empirical thermal viscosity exponent [1/K] *)
    rVisc_Ratio             : REAL;             (* Dynamic viscosity ratio relative to nominal *)

    (* --- Dynamic Gap State Estimation & Observability --- *)
    rGap_X_Diff             : REAL;     (* Measured differential radial gap X [um] *)
    rGap_Y_Diff             : REAL;     (* Measured differential radial gap Y [um] *)
    rGap_Z_Avg              : REAL;     (* Measured mean axial gap Z [um] *)
    rGap_X_Filtered         : REAL;     (* Low-pass filtered radial gap X [um] *)
    rGap_Y_Filtered         : REAL;     (* Low-pass filtered radial gap Y [um] *)
    rGap_X_Vel              : REAL;     (* Estimated radial velocity X [um/s] *)
    rGap_Y_Vel              : REAL;     (* Estimated radial velocity Y [um/s] *)
    rPrevGap_X              : REAL;     (* Prior cycle gap X [um] *)
    rPrevGap_Y              : REAL;     (* Prior cycle gap Y [um] *)

    (* --- State-Space Matrix Representation for Journal Dynamics (4x4, 4x2) --- *)
    (* State Vector x = [e_x (um), vel_x (um/s), e_y (um), vel_y (um/s)]^T *)
    a_gap                   : ARRAY [1..4, 1..4] OF REAL; (* Discrete state transition matrix A_gap *)
    b_gap                   : ARRAY [1..4, 1..2] OF REAL; (* Discrete input control matrix B_gap *)
    x_gap                   : ARRAY [1..4] OF REAL;       (* Current estimated system state *)
    x_gap_pred              : ARRAY [1..4] OF REAL;       (* 1-step receding horizon state prediction *)

    (* --- Model Predictive Control (MPC) Parameters & Accumulators --- *)
    rNominalGap_um          : REAL := 25.0;     (* Reference nominal equilibrium bearing gap [um] *)
    rMinSafeGap_um          : REAL := 12.0;     (* Critical minimum allowable oil film limit [um] *)
    rMaxSafeGap_um          : REAL := 42.0;     (* Critical maximum gap before pressure loss [um] *)
    rNominalSupplyP_bar     : REAL := 50.0;     (* Design hydraulic supply rail pressure [bar] *)
    rMinSupplyP_bar         : REAL := 38.0;     (* Lower pressure trip threshold [bar] *)
    rMaxValveAuthority_bar  : REAL := 22.0;     (* Maximum differential servo pressure command [bar] *)
    rMPC_K_P                : REAL := 2.650;    (* Proportional predictive gap gain [bar/um] *)
    rMPC_K_D                : REAL := 0.115;    (* Hydrodynamic velocity damping gain [bar/(um/s)] *)
    rMPC_K_I                : REAL := 0.620;    (* Steady-state integral disturbance gain [bar/(um*s)] *)
    rCrossCoupling_Gain     : REAL := 0.00028;  (* Hydrodynamic journal wedge cross-coupling [bar/(rpm*um)] *)
    rLoadFeedForward_Gain   : REAL := 0.0450;   (* Cutting force disturbance feedforward gain [bar/Nm] *)
    rIntError_X             : REAL := 0.0;      (* Integral error accumulator X-axis [um*s] *)
    rIntError_Y             : REAL := 0.0;      (* Integral error accumulator Y-axis [um*s] *)
    rIntError_Z             : REAL := 0.0;      (* Integral error accumulator Z-axis [um*s] *)

    (* --- Volumetric Thermal Nodal Network & Structural Expansion --- *)
    (* State Vector x_th = [T_nose_core, T_rear_core, T_col_core, T_shaft_core]^T in [deg C] *)
    a_th                    : ARRAY [1..4, 1..4] OF REAL; (* Thermal conductance/capacitance matrix *)
    b_th                    : ARRAY [1..4, 1..3] OF REAL; (* Heat dissipation coupling matrix *)
    x_thermal               : ARRAY [1..4] OF REAL;       (* Core nodal temperature states [deg C] *)
    q_shear_loss_W          : REAL;     (* Hydrostatic bearing viscous friction dissipation [W] *)
    q_motor_loss_W          : REAL;     (* Spindle drive copper and iron thermal losses [W] *)
    q_ambient_flux_W        : REAL;     (* Machine column convective ambient exchange [W] *)
    rAlpha_Steel            : REAL := 1.17E-5;  (* Linear thermal expansion of alloy spindle steel [1/K] *)
    rAlpha_Column           : REAL := 1.05E-5;  (* Linear thermal expansion of meehanite cast column [1/K] *)
    rSpindleSpan_mm         : REAL := 480.0;    (* Distance between front and rear bearing journals [mm] *)
    rToolOverhang_mm        : REAL := 195.0;    (* Gauge length from front bearing to tool center point [mm] *)
    rColumnHeight_mm        : REAL := 950.0;    (* Machine column effective thermal reference height [mm] *)
    rTiltAngle_ThetaY_rad   : REAL;     (* Thermal pitch tilt around Y axis [rad] *)
    rTiltAngle_ThetaX_rad   : REAL;     (* Thermal yaw tilt around X axis [rad] *)

    (* --- Finite State Machine Execution Sequencing --- *)
    iMachineState           : INT := 0; (* Active sequencer operational state *)
    iPrevState              : INT := -1;(* Previous cycle sequencer state *)
    tStateTimer             : TON;      (* State dwell timer *)
    tSettlingTimer          : TON;      (* Hydraulic stabilization timer *)
    bInitDone               : BOOL := FALSE; (* One-time cold boot initialization flag *)

    (* --- Working Iterators and Intermediates --- *)
    iIdx                    : INT;
    jIdx                    : INT;
    rMatAccum               : REAL;
    rDeltaT                 : REAL;
    rDeltaP_Raw_X           : REAL;
    rDeltaP_Raw_Y           : REAL;
    rDeltaP_Raw_Z           : REAL;
    rOmega_rad_s            : REAL;
    rRadialEccentricity     : REAL;
END_VAR

(* === INITIALIZATION OF DISCRETE DYNAMIC MATRICES === *)
IF NOT bInitDone THEN
    (* Continuous-time state equation: dx/dt = A_c * x + B_c * u
       Discretized via Euler / Bilinear Tustin with sampling delta T_s = 0.001 s *)
    (* Dynamic Journal Model: m * d2(x)/dt2 + C_hs * dx/dt + K_hs * x = Delta_P * A_pocket *)
    a_gap[1, 1] := 0.9985;  a_gap[1, 2] := 0.00098; a_gap[1, 3] := 0.00000; a_gap[1, 4] := 0.00000;
    a_gap[2, 1] := -2.850;  a_gap[2, 2] := 0.96500; a_gap[2, 3] := 0.04500; a_gap[2, 4] := 0.00010;
    a_gap[3, 1] := 0.0000;  a_gap[3, 2] := 0.00000; a_gap[3, 3] := 0.99850; a_gap[3, 4] := 0.00098;
    a_gap[4, 1] := -0.045;  a_gap[4, 2] := -0.0001; a_gap[4, 3] := -2.8500; a_gap[4, 4] := 0.96500;

    b_gap[1, 1] := 0.00012; b_gap[1, 2] := 0.00000;
    b_gap[2, 1] := 0.24500; b_gap[2, 2] := 0.00500;
    b_gap[3, 1] := 0.00000; b_gap[3, 2] := 0.00012;
    b_gap[4, 1] := -0.0050; b_gap[4, 2] := 0.24500;

    (* Thermal Discretized Model: C_th * dT/dt + K_th * T = Q_in *)
    a_th[1, 1] := 0.9992;   a_th[1, 2] := 0.00030;  a_th[1, 3] := 0.00000;  a_th[1, 4] := 0.00045;
    a_th[2, 1] := 0.0003;   a_th[2, 2] := 0.99910;  a_th[2, 3] := 0.00000;  a_th[2, 4] := 0.00040;
    a_th[3, 1] := 0.0000;   a_th[3, 2] := 0.00000;  a_th[3, 3] := 0.99985;  a_th[3, 4] := 0.00010;
    a_th[4, 1] := 0.0005;   a_th[4, 2] := 0.00045;  a_th[4, 3] := 0.00005;  a_th[4, 4] := 0.99890;

    b_th[1, 1] := 0.000085; b_th[1, 2] := 0.000020; b_th[1, 3] := 0.000005;
    b_th[2, 1] := 0.000065; b_th[2, 2] := 0.000015; b_th[2, 3] := 0.000005;
    b_th[3, 1] := 0.000005; b_th[3, 2] := 0.000010; b_th[3, 3] := 0.000120;
    b_th[4, 1] := 0.000040; b_th[4, 2] := 0.000095; b_th[4, 3] := 0.000010;

    (* Seed initial thermal state vector with ambient reading *)
    x_thermal[1] := rTemp_SpindleNose;
    x_thermal[2] := rTemp_RearBearing;
    x_thermal[3] := rTemp_MachineColumn;
    x_thermal[4] := (rTemp_SpindleNose + rTemp_RearBearing) * 0.5;

    bInitDone := TRUE;
END_IF;

(* === TASK EXECUTION DELTA TIME SANITIZATION === *)
IF rCycleTime_Sec <= 0.00001 OR rCycleTime_Sec > 0.100 THEN
    rDeltaT := 0.001; (* Default to 1 ms deterministic task scan *)
ELSE
    rDeltaT := rCycleTime_Sec;
END_IF;

(* === 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) PRESSURE VOTING === *)
(* Transmitter Plausibility Bounds: 0.0 to 100.0 bar *)
bCh1_Healthy := (rSupplyPressure_Ch1 >= 5.0) AND (rSupplyPressure_Ch1 <= 95.0);
bCh2_Healthy := (rSupplyPressure_Ch2 >= 5.0) AND (rSupplyPressure_Ch2 <= 95.0);
bCh3_Healthy := (rSupplyPressure_Ch3 >= 5.0) AND (rSupplyPressure_Ch3 <= 95.0);

(* Discrepancy Analysis (Inter-channel delta tolerance = 3.5 bar) *)
rDiff_12 := ABS(rSupplyPressure_Ch1 - rSupplyPressure_Ch2);
rDiff_23 := ABS(rSupplyPressure_Ch2 - rSupplyPressure_Ch3);
rDiff_31 := ABS(rSupplyPressure_Ch3 - rSupplyPressure_Ch1);

IF (rDiff_12 > 3.5) AND (rDiff_31 > 3.5) AND bCh1_Healthy THEN
    bCh1_Healthy := FALSE; (* Ch1 has diverged from consensus *)
END_IF;
IF (rDiff_12 > 3.5) AND (rDiff_23 > 3.5) AND bCh2_Healthy THEN
    bCh2_Healthy := FALSE; (* Ch2 has diverged from consensus *)
END_IF;
IF (rDiff_23 > 3.5) AND (rDiff_31 > 3.5) AND bCh3_Healthy THEN
    bCh3_Healthy := FALSE; (* Ch3 has diverged from consensus *)
END_IF;

(* Count healthy pressure channels *)
iValidChannelCount := 0;
IF bCh1_Healthy THEN iValidChannelCount := iValidChannelCount + 1; END_IF;
IF bCh2_Healthy THEN iValidChannelCount := iValidChannelCount + 1; END_IF;
IF bCh3_Healthy THEN iValidChannelCount := iValidChannelCount + 1; END_IF;

(* Median Selection & Degraded Voting Algorithm *)
IF iValidChannelCount = 3 THEN
    bTMR_Degraded := FALSE;
    (* 2oo3 Median Voter *)
    IF (rSupplyPressure_Ch1 >= rSupplyPressure_Ch2 AND rSupplyPressure_Ch1 <= rSupplyPressure_Ch3) OR
       (rSupplyPressure_Ch1 <= rSupplyPressure_Ch2 AND rSupplyPressure_Ch1 >= rSupplyPressure_Ch3) THEN
        rPressVoted := rSupplyPressure_Ch1;
    ELSIF (rSupplyPressure_Ch2 >= rSupplyPressure_Ch1 AND rSupplyPressure_Ch2 <= rSupplyPressure_Ch3) OR
          (rSupplyPressure_Ch2 <= rSupplyPressure_Ch1 AND rSupplyPressure_Ch2 >= rSupplyPressure_Ch3) THEN
        rPressVoted := rSupplyPressure_Ch2;
    ELSE
        rPressVoted := rSupplyPressure_Ch3;
    END_IF;
ELSIF iValidChannelCount = 2 THEN
    bTMR_Degraded := TRUE; (* Degraded 1oo2 Voting Mode *)
    IF bCh1_Healthy AND bCh2_Healthy THEN
        rPressVoted := (rSupplyPressure_Ch1 + rSupplyPressure_Ch2) * 0.5;
    ELSIF bCh2_Healthy AND bCh3_Healthy THEN
        rPressVoted := (rSupplyPressure_Ch2 + rSupplyPressure_Ch3) * 0.5;
    ELSE
        rPressVoted := (rSupplyPressure_Ch1 + rSupplyPressure_Ch3) * 0.5;
    END_IF;
ELSIF iValidChannelCount = 1 THEN
    bTMR_Degraded := TRUE;
    IF bCh1_Healthy THEN rPressVoted := rSupplyPressure_Ch1;
    ELSIF bCh2_Healthy THEN rPressVoted := rSupplyPressure_Ch2;
    ELSE rPressVoted := rSupplyPressure_Ch3;
    END_IF;
ELSE
    (* Total TMR Sensor Failure *)
    rPressVoted := 0.0;
    bTMR_Degraded := TRUE;
END_IF;

(* === DYNAMIC FLUID VISCOSITY ESTIMATION (ASTM D341 EMPIRICAL MODEL) === *)
(* Correct for temperature-dependent Reynolds shear thinning in hydrostatic pockets *)
rEffectiveViscosity_cSt := rVisc_Nominal_cSt * EXP(-rVisc_Slope_Beta * (rTemp_OilSump - rT_Ref_DegC));
IF rEffectiveViscosity_cSt < 12.0 THEN
    rEffectiveViscosity_cSt := 12.0; (* Lower physical floor to prevent numeric instability *)
ELSIF rEffectiveViscosity_cSt > 150.0 THEN
    rEffectiveViscosity_cSt := 150.0; (* Cold oil upper limit *)
END_IF;
rVisc_Ratio := rEffectiveViscosity_cSt / rVisc_Nominal_cSt;

(* === SENSOR FUSION & BEARING GAP RECONSTRUCTION === *)
(* Differential opposing eddy-current sensor pairs reject common-mode thermal shaft growth *)
rGap_X_Diff := (rGapRadial_X1 - rGapRadial_X2) * 0.5;
rGap_Y_Diff := (rGapRadial_Y1 - rGapRadial_Y2) * 0.5;
rGap_Z_Avg  := (rGapAxial_Z1 + rGapAxial_Z2) * 0.5;

(* 1st-Order Low-Pass Filter on Gap Measurements (Cutoff ~ 250 Hz) *)
rGap_X_Filtered := rGap_X_Filtered + (rGap_X_Diff - rGap_X_Filtered) * (rDeltaT / (rDeltaT + 0.00065));
rGap_Y_Filtered := rGap_Y_Filtered + (rGap_Y_Diff - rGap_Y_Filtered) * (rDeltaT / (rDeltaT + 0.00065));

(* Estimate Radial Velocities *)
rGap_X_Vel := (rGap_X_Filtered - rPrevGap_X) / rDeltaT;
rGap_Y_Vel := (rGap_Y_Filtered - rPrevGap_Y) / rDeltaT;
rPrevGap_X := rGap_X_Filtered;
rPrevGap_Y := rGap_Y_Filtered;

(* Compute Eccentricity & Minimum Lubricating Film Thickness *)
rRadialEccentricity := SQRT((rGap_X_Diff * rGap_X_Diff) + (rGap_Y_Diff * rGap_Y_Diff));
rBearingFilmThickness_Est := rNominalGap_um - rRadialEccentricity;

(* === STATE OBSERVER & MODEL PREDICTIVE GAP REGULATION (MPC) === *)
(* Update Observed State Vector *)
x_gap[1] := rGap_X_Filtered;
x_gap[2] := rGap_X_Vel;
x_gap[3] := rGap_Y_Filtered;
x_gap[4] := rGap_Y_Vel;

(* 1-Step Receding Horizon State Prediction: x_pred = A_gap * x + B_gap * u *)
FOR iIdx := 1 TO 4 DO
    rMatAccum := 0.0;
    FOR jIdx := 1 TO 4 DO
        rMatAccum := rMatAccum + a_gap[iIdx, jIdx] * x_gap[jIdx];
    END_FOR;
    x_gap_pred[iIdx] := rMatAccum + b_gap[iIdx, 1] * rServoValvePressureCmd_X + b_gap[iIdx, 2] * rServoValvePressureCmd_Y;
END_FOR;

(* Angular velocity conversion [rad/s] *)
rOmega_rad_s := rSpindleSpeed_Act * 0.104719755;

(* Anti-Windup Error Integrators *)
IF ABS(x_gap[1]) > 0.05 THEN
    rIntError_X := rIntError_X + (0.0 - x_gap[1]) * rDeltaT;
    IF rIntError_X > 15.0 THEN rIntError_X := 15.0; ELSIF rIntError_X < -15.0 THEN rIntError_X := -15.0; END_IF;
ELSE
    rIntError_X := rIntError_X * 0.9995; (* Slow bleed *)
END_IF;

IF ABS(x_gap[3]) > 0.05 THEN
    rIntError_Y := rIntError_Y + (0.0 - x_gap[3]) * rDeltaT;
    IF rIntError_Y > 15.0 THEN rIntError_Y := 15.0; ELSIF rIntError_Y < -15.0 THEN rIntError_Y := -15.0; END_IF;
ELSE
    rIntError_Y := rIntError_Y * 0.9995;
END_IF;

IF ABS(rNominalGap_um - rGap_Z_Avg) > 0.05 THEN
    rIntError_Z := rIntError_Z + (rNominalGap_um - rGap_Z_Avg) * rDeltaT;
    IF rIntError_Z > 20.0 THEN rIntError_Z := 20.0; ELSIF rIntError_Z < -20.0 THEN rIntError_Z := -20.0; END_IF;
END_IF;

(* Multi-Variable MPC Control Law with Hydrodynamic Cross-Coupling Decoupling *)
(* Hydrodynamic rotation induces cross-axis stiffness: F_y = k_xy * x, F_x = -k_yx * y *)
rDeltaP_Raw_X := -(rMPC_K_P * x_gap_pred[1]) - (rMPC_K_D * x_gap_pred[2]) + (rMPC_K_I * rIntError_X)
                 - (rCrossCoupling_Gain * rOmega_rad_s * x_gap_pred[3] * rVisc_Ratio);

rDeltaP_Raw_Y := -(rMPC_K_P * x_gap_pred[3]) - (rMPC_K_D * x_gap_pred[4]) + (rMPC_K_I * rIntError_Y)
                 + (rCrossCoupling_Gain * rOmega_rad_s * x_gap_pred[1] * rVisc_Ratio)
                 + (rLoadFeedForward_Gain * rSpindleLoadTorque);

rDeltaP_Raw_Z := (rMPC_K_P * 0.85 * (rNominalGap_um - rGap_Z_Avg)) + (rMPC_K_I * 0.50 * rIntError_Z);

(* Saturate commands within valve authority limits *)
IF rDeltaP_Raw_X > rMaxValveAuthority_bar THEN rServoValvePressureCmd_X := rMaxValveAuthority_bar;
ELSIF rDeltaP_Raw_X < -rMaxValveAuthority_bar THEN rServoValvePressureCmd_X := -rMaxValveAuthority_bar;
ELSE rServoValvePressureCmd_X := rDeltaP_Raw_X;
END_IF;

IF rDeltaP_Raw_Y > rMaxValveAuthority_bar THEN rServoValvePressureCmd_Y := rMaxValveAuthority_bar;
ELSIF rDeltaP_Raw_Y < -rMaxValveAuthority_bar THEN rServoValvePressureCmd_Y := -rMaxValveAuthority_bar;
ELSE rServoValvePressureCmd_Y := rDeltaP_Raw_Y;
END_IF;

IF rDeltaP_Raw_Z > rMaxValveAuthority_bar THEN rServoValvePressureCmd_Z := rMaxValveAuthority_bar;
ELSIF rDeltaP_Raw_Z < -rMaxValveAuthority_bar THEN rServoValvePressureCmd_Z := -rMaxValveAuthority_bar;
ELSE rServoValvePressureCmd_Z := rDeltaP_Raw_Z;
END_IF;

(* === VOLUMETRIC REAL-TIME THERMAL STATE OBSERVER & COMPENSATION === *)
(* Calculate Mechanical Shear Loss: P_visc = mu * A * (omega * R)^2 / h *)
q_shear_loss_W := 0.00034 * rEffectiveViscosity_cSt * (rOmega_rad_s * rOmega_rad_s);

(* Calculate Electromagnetic Stator Loss: P_loss = k_cu * Torque^2 + k_fe * Speed *)
q_motor_loss_W := (0.12 * rSpindleLoadTorque * rSpindleLoadTorque) + (0.045 * ABS(rSpindleSpeed_Act));

(* Convective Heat Flux from Machine Frame to Ambient Air *)
q_ambient_flux_W := 18.5 * (rTemp_AmbientAir - x_thermal[3]);

(* Thermal State Matrix Integration: x_th(k+1) = A_th * x_th(k) + B_th * Q_in *)
FOR iIdx := 1 TO 4 DO
    rMatAccum := 0.0;
    FOR jIdx := 1 TO 4 DO
        rMatAccum := rMatAccum + a_th[iIdx, jIdx] * x_thermal[jIdx];
    END_FOR;
    x_thermal[iIdx] := rMatAccum + b_th[iIdx, 1] * q_shear_loss_W + b_th[iIdx, 2] * q_motor_loss_W + b_th[iIdx, 3] * q_ambient_flux_W;
END_FOR;

(* Volumetric Kinematic Error Mapping at Tool Center Point (TCP) *)
(* Axial Spindle Elongation Z: delta_Z = alpha_steel * L_spindle * delta_T *)
rThermalCompOffset_Z := -(rAlpha_Steel * rSpindleSpan_mm * 1000.0 * (x_thermal[4] - 20.0));

(* Thermal Pitch Tilt Theta_Y due to front/rear bearing temperature gradient *)
rTiltAngle_ThetaY_rad := ((x_thermal[1] - x_thermal[2]) * rAlpha_Steel * 1000.0) / rSpindleSpan_mm;

(* Tool Center Point Abbe Offset Projection in X *)
rThermalCompOffset_X := -( (rAlpha_Column * rColumnHeight_mm * 1000.0 * (x_thermal[3] - 20.0))
