            IF (rBearingFilmThickness_Est >= 16.0) AND (rPressVoted >= 42.0) THEN
                iMachineState := 30; (* Advance to Active Regulation Idle *)
            ELSE
                iMachineState := 99; (* Gap float failure *)
            END_IF;
